+/** Picks `ko` or `en` from an Accept-Language header (q-values, region tags), else the default. */
+export function pickLanguage(header, fallback = config.defaultLanguage) {
+  let best = null;
+  let bestQ = 0;
+  String(header ?? "").split(",").forEach((part) => {
+    const [tag, ...attrs] = part.trim().split(";");
+    const base = tag.trim().toLowerCase().split("-")[0];
+    const qAttr = attrs.map((a) => a.trim()).find((a) => /^q=/i.test(a));
+    const q = qAttr ? Number(qAttr.slice(2)) : 1;
+    if ((base === "ko" || base === "en") && Number.isFinite(q) && q > bestQ) {
+      best = base;
+      bestQ = q;
+    }
+  });
+  return best ?? fallback;
+}
